CREATE TYPE public.app_role AS ENUM ('admin');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_roles ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid, public.app_role) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.has_role(uuid, public.app_role) TO authenticated, service_role;
CREATE TABLE public.services (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text NOT NULL UNIQUE CHECK(length(slug)<=100), title text NOT NULL CHECK(length(title)<=150), description text NOT NULL DEFAULT '' CHECK(length(description)<=5000), audience text, duration_minutes integer CHECK(duration_minutes>0), price_minor bigint CHECK(price_minor>=0), currency text NOT NULL DEFAULT 'NGN' CHECK(currency='NGN'), delivery_format text, active boolean NOT NULL DEFAULT false, published boolean NOT NULL DEFAULT false, sort_order integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.services TO anon;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.services TO authenticated;
GRANT ALL ON public.services TO service_role;
ALTER TABLE public.services ENABLE ROW LEVEL SECURITY;
CREATE POLICY published_services ON public.services FOR SELECT TO anon,authenticated USING(published AND active);
CREATE POLICY admin_services ON public.services FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.pages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text NOT NULL, title text NOT NULL CHECK(length(title)<=200), body text NOT NULL DEFAULT '' CHECK(length(body)<=30000), published boolean NOT NULL DEFAULT false, updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX published_page_slug ON public.pages(slug) WHERE published;
GRANT SELECT ON public.pages TO anon;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.pages TO authenticated;
GRANT ALL ON public.pages TO service_role;
ALTER TABLE public.pages ENABLE ROW LEVEL SECURITY;
CREATE POLICY published_pages ON public.pages FOR SELECT TO anon,authenticated USING(published);
CREATE POLICY admin_pages ON public.pages FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.faqs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), question text NOT NULL CHECK(length(question)<=300), answer text NOT NULL CHECK(length(answer)<=5000), published boolean NOT NULL DEFAULT false, sort_order integer NOT NULL DEFAULT 0);
GRANT SELECT ON public.faqs TO anon;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.faqs TO authenticated;
GRANT ALL ON public.faqs TO service_role;
ALTER TABLE public.faqs ENABLE ROW LEVEL SECURITY;
CREATE POLICY published_faqs ON public.faqs FOR SELECT TO anon,authenticated USING(published);
CREATE POLICY admin_faqs ON public.faqs FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.public_settings (key text PRIMARY KEY CHECK(length(key)<=100), value text NOT NULL DEFAULT '' CHECK(length(value)<=5000), published boolean NOT NULL DEFAULT false);
GRANT SELECT ON public.public_settings TO anon;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.public_settings TO authenticated;
GRANT ALL ON public.public_settings TO service_role;
ALTER TABLE public.public_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY published_settings ON public.public_settings FOR SELECT TO anon,authenticated USING(published);
CREATE POLICY admin_settings ON public.public_settings FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.rate_limit_buckets (key text PRIMARY KEY, window_start timestamptz NOT NULL DEFAULT now(), attempts integer NOT NULL DEFAULT 1);
GRANT ALL ON public.rate_limit_buckets TO service_role;
ALTER TABLE public.rate_limit_buckets ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.consume_contact_limit(bucket text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n integer; BEGIN INSERT INTO public.rate_limit_buckets(key) VALUES(bucket) ON CONFLICT(key) DO UPDATE SET attempts=CASE WHEN rate_limit_buckets.window_start < now()-interval '1 hour' THEN 1 ELSE rate_limit_buckets.attempts+1 END, window_start=CASE WHEN rate_limit_buckets.window_start < now()-interval '1 hour' THEN now() ELSE rate_limit_buckets.window_start END RETURNING attempts INTO n; RETURN n<=5; END $$;
REVOKE ALL ON FUNCTION public.consume_contact_limit(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.consume_contact_limit(text) TO service_role;